                options: [{"en":"√5 + 2","ta":"√5 + 2","hi":"√5 + 2"},{"en":"√5 - 2","ta":"√5 - 2","hi":"√5 - 2"},{"en":"1 / (√5 + 2)","ta":"1 / (√5 + 2)","hi":"1 / (√5 + 2)"},{"en":"5 - 4","ta":"5 - 4","hi":"5 - 4"}],
